const alerts = $input.all().map(item => item.json).filter(a => a.Timestamp);

// Aggregate stats
const total = alerts.length;
const anomalies = alerts.filter(a => a.Anomaly && a.Anomaly !== 'NORMAL');
const byType = {};
anomalies.forEach(a => { byType[a.Anomaly] = (byType[a.Anomaly] || 0) + 1; });
const bySeverity = {};
anomalies.forEach(a => { bySeverity[a.Severity] = (bySeverity[a.Severity] || 0) + 1; });
const byNode = {};
alerts.forEach(a => {
  const n = a.Node || 'Unknown';
  if (!byNode[n]) byNode[n] = { total: 0, anomalies: 0 };
  byNode[n].total++;
  if (a.Anomaly && a.Anomaly !== 'NORMAL') byNode[n].anomalies++;
});
const autonomous = alerts.filter(a => a.Escalation === 'AUTONOMOUS').length;
const humanReview = alerts.filter(a => a.Escalation === 'HUMAN_REVIEW').length;
const escalated = alerts.filter(a => a.Escalation === 'ESCALATED').length;

// Most problematic node
const worstNode = Object.entries(byNode).sort((a,b) => b[1].anomalies - a[1].anomalies)[0];

// Network health score
const healthPct = total > 0 ? Math.round(((total - anomalies.length) / total) * 100) : 100;

const now = new Date();
const dateStr = now.toISOString().split('T')[0];

const typeReport = Object.entries(byType).map(([t,c]) => `  • ${t}: ${c}`).join('\n');
const sevReport = Object.entries(bySeverity).map(([s,c]) => `  • ${s}: ${c}`).join('\n');
const nodeReport = Object.entries(byNode).map(([n,s]) => `  • ${n}: ${s.total} olay, ${s.anomalies} anomali`).join('\n');

const summaryText = `📊 SkyOps Günlük Rapor — ${dateStr}\n\n🔢 Toplam Olay: ${total}\n⚠️ Anomali: ${anomalies.length} (${total > 0 ? Math.round((anomalies.length/total)*100) : 0}%)\n🏥 Ağ Sağlık Skoru: ${healthPct}%\n\n📋 Anomali Türleri:\n${typeReport || '  • Yok'}\n\n🎯 Ciddiyet Dağılımı:\n${sevReport || '  • Yok'}\n\n🖥️ Node Bazlı:\n${nodeReport}\n\n🤖 Eskalasyon Dağılımı:\n  • Otonom: ${autonomous}\n  • İnsan Onayı: ${humanReview}\n  • Eskalasyon: ${escalated}\n\n${worstNode ? `⚠️ En sorunlu düğüm: ${worstNode[0]} (${worstNode[1].anomalies} anomali)` : '✅ Tüm düğümler stabil'}\n\n🕐 Rapor zamanı: ${now.toISOString()}`;

// Summary row for Google Sheets
const summaryRow = {
  Timestamp: now.toISOString(),
  Node: 'GÜNLÜK RAPOR',
  Severity: healthPct >= 80 ? 'LOW' : healthPct >= 50 ? 'MEDIUM' : 'CRITICAL',
  Anomaly: `DAILY_SUMMARY`,
  Confidence: String(healthPct / 100),
  Escalation: 'AUTONOMOUS',
  'Healing Action': `Toplam: ${total}, Anomali: ${anomalies.length}, Sağlık: ${healthPct}%`,
  'Root Cause': `En sorunlu: ${worstNode ? worstNode[0] : 'Yok'}`
};

return [{ json: { summaryText, summaryRow, dateStr } }];
